//! Decals from code: textures generated by a closure, projected onto whatever they overlap.
//!
//! - **Forward decals** (`ForwardDecal`, any GPU): a unit quad facing +Y in local space, scaled
//!   by the transform, alpha-blended onto the depth buffer underneath. [`spawn_decal`] builds
//!   the material; the look keeps a depth prepass on every 3D camera while decals exist
//!   (`gfx::KeepDepthPrepass`).
//! - **Clustered decals** (`ClusteredDecal`): Bevy's projector boxes (along local +Z), shaded in
//!   the main PBR pass. They need the `look_clustered_decals` cargo feature (Bevy's
//!   `pbr_clustered_decals`) and bindless textures, which Bevy 0.19 disables on Metal; elsewhere
//!   they are skipped silently. Spawn `(ClusteredDecal { base_color_texture: Some(img), .. }, Transform)`.

use bevy::asset::RenderAssetUsages;
use bevy::image::{ImageAddressMode, ImageSampler, ImageSamplerDescriptor};
use bevy::pbr::decal::{ForwardDecal, ForwardDecalMaterial, ForwardDecalMaterialExt};
use bevy::pbr::ExtendedMaterial;
use bevy::prelude::*;
use bevy::render::render_resource::{Extent3d, TextureDimension, TextureFormat};

use crate::gfx::KeepDepthPrepass;

/// An sRGB RGBA8 image from `f(uv) -> [r, g, b, a]` (0..1), clamped edges, mipmapped.
pub fn decal_image(size: u32, f: impl Fn(Vec2) -> [f32; 4]) -> Image {
    let n = size.max(2);
    let mut data = Vec::with_capacity((n * n * 4) as usize);
    for y in 0..n {
        for x in 0..n {
            let uv = Vec2::new((x as f32 + 0.5) / n as f32, (y as f32 + 0.5) / n as f32);
            for c in f(uv) {
                data.push((c.clamp(0.0, 1.0) * 255.0 + 0.5) as u8);
            }
        }
    }
    let mut img = Image::new(Extent3d { width: n, height: n, depth_or_array_layers: 1 }, TextureDimension::D2, data, TextureFormat::Rgba8UnormSrgb, RenderAssetUsages::default());
    img.sampler = ImageSampler::Descriptor(ImageSamplerDescriptor {
        address_mode_u: ImageAddressMode::ClampToEdge,
        address_mode_v: ImageAddressMode::ClampToEdge,
        ..ImageSamplerDescriptor::linear()
    });
    crate::gfx::build_mips(&mut img);
    img
}

/// A forward-decal material: `base` (alpha-blended PBR, e.g. a texture with transparent edges)
/// fading out within `depth_fade` metres of the surface.
pub fn decal_material(base: StandardMaterial, depth_fade: f32) -> ForwardDecalMaterial<StandardMaterial> {
    ExtendedMaterial { base: StandardMaterial { alpha_mode: AlphaMode::Blend, ..base }, extension: ForwardDecalMaterialExt { depth_fade_factor: depth_fade } }
}

/// Spawns a forward decal with `material` at `transform` (local +Y is the projection normal;
/// x/z scale is the decal size, y scale its depth range).
pub fn spawn_decal(commands: &mut Commands, material: Handle<ForwardDecalMaterial<StandardMaterial>>, transform: Transform) -> Entity {
    commands.spawn((Name::new("Decal"), ForwardDecal, MeshMaterial3d(material), transform)).id()
}

/// Forward decals read the depth prepass: keep one on every 3D camera while any exist (the
/// main camera's is marked [`KeepDepthPrepass`] so quality pruning leaves it).
pub fn keep_depth_for_decals(
    mut commands: Commands,
    decals: Query<(), With<ForwardDecal>>,
    cams: Query<(Entity, Has<KeepDepthPrepass>, Has<bevy::core_pipeline::prepass::DepthPrepass>), With<Camera3d>>,
) {
    let want = !decals.is_empty();
    for (e, keep, depth) in &cams {
        if want && (!keep || !depth) {
            commands.entity(e).insert((KeepDepthPrepass, bevy::core_pipeline::prepass::DepthPrepass));
        } else if !want && keep {
            commands.entity(e).remove::<KeepDepthPrepass>();
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decal_image_from_closure() {
        let img = decal_image(8, |uv| [uv.x, uv.y, 0.0, 1.0]);
        assert_eq!(img.texture_descriptor.size.width, 8);
        assert_eq!(img.texture_descriptor.mip_level_count, 4);
        let d = img.data.as_ref().unwrap();
        // First texel: uv ≈ (1/16, 1/16).
        assert_eq!(d[0], (0.0625f32 * 255.0 + 0.5) as u8);
        assert_eq!(d[3], 255);
    }
}
